def transform(grid):
    rows, cols = len(grid), len(grid[0])
    sep_color = grid[3][0]  # separator color

    # Find separator rows and columns
    sep_rows = [i for i in range(rows) if all(grid[i][j] == sep_color for j in range(cols))]
    sep_cols = [j for j in range(cols) if all(grid[i][j] == sep_color for i in range(rows))]

    # Determine background as top-left non-separator value
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != sep_color:
                background = grid[i][j]
                break
        else:
            continue
        break

    # Find secondary color (unique non-sep, non-bg color)
    secondary = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != sep_color and grid[i][j] != background:
                secondary = grid[i][j]
                break
        if secondary:
            break

    output = []
    for r_idx in range(len(sep_rows) + 1):
        row_out = []
        r_start = sep_rows[r_idx - 1] + 1 if r_idx > 0 else 0
        r_end = sep_rows[r_idx] - 1 if r_idx < len(sep_rows) else rows - 1

        for c_idx in range(len(sep_cols) + 1):
            c_start = sep_cols[c_idx - 1] + 1 if c_idx > 0 else 0
            c_end = sep_cols[c_idx] - 1 if c_idx < len(sep_cols) else cols - 1

            has_secondary = False
            for i in range(r_start, r_end + 1):
                for j in range(c_start, c_end + 1):
                    if grid[i][j] == secondary:
                        has_secondary = True
                        break
                if has_secondary:
                    break

            if has_secondary:
                row_out.append(1)
            else:
                row_out.append(background)
        output.append(row_out)

    return output
